### mini_pkg.calc.RunningStats.add
signature: add(self, x)
    def add(self, x):
        self._values.append(x)
        return self

### mini_pkg.calc.RunningStats.count
signature: count(self)
    def count(self):
        return len(self._values)

### mini_pkg.calc.RunningStats.mean
signature: mean(self)
    def mean(self):
        if not self._values:
            raise ValueError("no values")
        return sum(self._values) / len(self._values)

### mini_pkg.calc.ceil_div
signature: ceil_div(a, b)
def ceil_div(a, b):
    """Return ceil(a / b) for positive integers."""
    quotient, remainder = divmod(a, b)
    return quotient + bool(remainder)

### mini_pkg.calc.clamp
signature: clamp(value, low, high)
def clamp(value, low, high):
    """Clamp value into the inclusive range [low, high].

    Bounds given in either order are accepted."""
    if low > high:
        low, high = high, low
    if value < low:
        return low
    if value > high:
        return high
    return value
